insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NZ:civil-engineer','2026-08-11',null,56.49,117500,20,0,0,0,8,10,0,10,5,53,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 233211 Civil Engineer; Tahatu also includes structural, geotechnical, transport and related civil specialisations, but the canonical profile is anchored to 233211.','shortage_note','Current Green List Tier 1 status is used as the strongest direct policy-demand signal; 20/20.','visa_basis','Green List Tier 1 can support Straight to Residence when the listed engineering qualification or accepted Engineering New Zealand pathway is met; 10/10.','salary_method','Midpoint of Tahatu current most-common Civil Engineer annual pay range NZD 81,000-154,000; 10/10.','entry_basis','A BE(Hons) or comparable professional civil-engineering qualification is the standard route; 8/15.','entry_burden_basis','Engineering New Zealand states engineers do not generally have to be registered to work, although some sign-off roles require CPEng; 5/5.'),'2026-08-11'),
('NZ:mechanical-engineer','2026-08-11',null,47.36,98500,20,0,0,0,8,8,0,10,5,51,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 233512 Mechanical Engineer.','shortage_note','Current Green List Tier 1 status is direct policy evidence of demand; 20/20.','visa_basis','Tier 1 Straight to Residence when the Green List engineering qualification or accepted Engineering New Zealand pathway is met; 10/10.','salary_method','Midpoint of Tahatu current most-common Mechanical Engineer annual pay range NZD 72,000-125,000; 8/10.','entry_basis','Professional mechanical-engineering study is the standard direct route; 8/15.','entry_burden_basis','No universal statutory licence applies to the generic profession; CPEng is optional for many jobs but required for some regulated sign-off work; 5/5.'),'2026-08-11'),
('NZ:electrical-engineer','2026-08-11',null,55.77,116000,20,0,0,0,8,10,0,10,4,52,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 233311 Electrical Engineer.','shortage_note','Current Green List Tier 1 status is direct policy evidence of demand; 20/20.','visa_basis','Tier 1 Straight to Residence when the listed engineering qualification or accepted Engineering New Zealand pathway is met; the Green List itself does not require EWRB registration for every role; 10/10.','salary_method','Midpoint of Tahatu current most-common Electrical Engineer annual pay range NZD 82,000-150,000; 10/10.','entry_basis','A bachelor-level electrical-engineering qualification is the standard route; 8/15.','entry_burden_basis','Engineering practice is not universally licensed, but carrying out or supervising prescribed electrical work requires the appropriate EWRB registration and current practising licence; 4/5.'),'2026-08-11'),
('NZ:manufacturing-engineer','2026-08-11',null,45.19,94000,20,0,0,0,10,8,0,10,5,53,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Canonical Manufacturing Engineer is mapped to ANZSCO 233513 Production or Plant Engineer because the official occupation covers planning and management of manufacturing activities and plant performance.','shortage_note','ANZSCO 233513 is on the current Green List Tier 1; 20/20.','visa_basis','Tier 1 Straight to Residence when the Green List engineering qualification or accepted Engineering New Zealand pathway is met; 10/10.','salary_method','Midpoint of Tahatu current most-common Manufacturing Engineer annual pay range NZD 88,000-100,000; 8/10.','entry_basis','Tahatū allows a relevant manufacturing/engineering tertiary qualification or a trade certificate plus relevant production/process experience; 10/15.','entry_burden_basis','No universal statutory occupational licence; CPEng may be useful for particular responsibilities but is not generally mandatory; 5/5.'),'2026-08-11'),
('NZ:industrial-engineer','2026-08-11',null,47.36,98500,20,0,0,0,8,8,0,10,5,51,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 233511 Industrial Engineer is an exact canonical match.','shortage_note','Current Green List Tier 1 status is direct policy evidence of demand; 20/20.','visa_basis','Tier 1 Straight to Residence when the listed engineering qualification or accepted Engineering New Zealand pathway is met; 10/10.','salary_method','Midpoint of Tahatu current most-common Industrial Engineer annual pay range NZD 73,000-124,000; 8/10.','entry_basis','Tahatū identifies BE(Hons) or Bachelor of Engineering Technology as direct routes; 8/15.','entry_burden_basis','No universal statutory registration is required for generic engineering work; CPEng is optional for many roles; 5/5.'),'2026-08-11'),
('NZ:chemical-engineer','2026-08-11',null,53.37,111000,20,0,0,0,8,10,0,10,5,53,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 233111 Chemical Engineer.','shortage_note','Current Green List Tier 1 status is direct policy evidence of demand; 20/20.','visa_basis','Tier 1 Straight to Residence when the listed professional-engineering qualification or accepted Engineering New Zealand pathway is met; 10/10.','salary_method','Midpoint of Tahatu current most-common Chemical Engineer annual pay range NZD 77,000-145,000; 10/10.','entry_basis','Tahatū identifies BE(Hons), Food Technology (Honours) or relevant process/resources engineering study as direct routes; 8/15.','entry_burden_basis','No universal statutory licence applies to the generic profession; CPEng can be valuable but is not mandatory for most engineering employment; 5/5.'),'2026-08-11'),
('NZ:environmental-engineer','2026-08-11',null,51.68,107500,20,0,0,0,8,10,0,10,5,53,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 233915 Environmental Engineer.','shortage_note','Current Green List Tier 1 status is direct policy evidence of demand; 20/20.','visa_basis','Tier 1 Straight to Residence when the listed engineering qualification or accepted Engineering New Zealand pathway is met; 10/10.','salary_method','Midpoint of Tahatu current most-common Environmental Engineer annual pay range NZD 74,000-141,000; 10/10.','entry_basis','A BE(Hons) or similar environmental-engineering qualification is the standard route; 8/15.','entry_burden_basis','No universal statutory registration is required to work as an engineer, although CPEng can be required for regulated sign-off work; 5/5.'),'2026-08-11'),
('NZ:engineering-technician','2026-08-11',null,38.22,79500,0,0,0,0,15,6,0,5,5,31,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Generic Engineering Technician is conservatively anchored to ANZSCO 312999 Building and Engineering Technicians nec. Specific civil, electrical, electronic and mechanical technician codes are not rolled into this generic profile.','shortage_note','No current Green List credit is assigned to generic 312999. Its announced Skilled Migrant Category Trades and Technician pathway takes effect on 24 August 2026 and is not pre-scored on 11 August 2026.','visa_basis','Current standard skilled-work treatment is used; future SMC residence settings are disclosed but not awarded before commencement; 5/10.','salary_method','Midpoint of Tahatu current most-common Mechanical Engineering Technician annual pay range NZD 61,000-98,000, used as a transparent representative technician proxy; 6/10.','entry_basis','Diploma, certificate, apprenticeship and experience routes make technician entry materially more accessible than professional engineer roles; 15/15.','entry_burden_basis','No universal registration applies to the generic 312999 scope; specialist electrical or other regulated work can require separate licensing; 5/5.'),'2026-08-11')
